from pathlib import Path
import json,hashlib
from PIL import Image
import numpy as np
R=Path(__file__).parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def inspect(file):
 p=R/file; im=Image.open(p); a=np.array(im.getchannel('A')); yy,xx=np.where(a>=32)
 return dict(file=file,width=im.width,height=im.height,mode=im.mode,sha256=sha(p),boundsAlpha32=[int(xx.min()),int(yy.min()),int(xx.max()+1),int(yy.max()+1)],alpha=dict(min=int(a.min()),max=int(a.max()),transparentPixels=int((a==0).sum()),partialPixels=int(((a>0)&(a<255)).sum())),nativeBytesPreserved=True)
cfg=json.loads((R/'measurements.json').read_text(encoding='utf-8'))
data=[]
for c in cfg:
 c.update(inspect(c['file']));data.append(c)
sources=json.loads((R/'source-inputs.json').read_text(encoding='utf-8'))
manifest=dict(task='MAIN01-20261110-D820F076',iteration=2,role='characters',assets=data,sources=sources,measurementMethod='Native PNG inspection; alpha>=32 bounds; manually identified hair top/sole and boot support center. Sword/cape/shield are excluded from bodyHeight. Scalp crown hidden by hair: visual estimate, not exact anatomy.',normalization='CSS uniform scale only. Original generated PNG bytes never resized/reencoded.',gameIntegration=False)
(R/'asset-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>발로르 · 차수2 실루엣 수정 검토</title><style>
*{box-sizing:border-box}body{margin:0;background:#edf0f4;color:#202b3a;font:16px system-ui}body.dark{background:#141b25;color:#edf1f8}header{padding:16px 24px}h1{font-size:23px;margin:0 0 8px}p{margin:8px 0}button{padding:8px 14px;margin:3px;border:1px solid #8592a2;border-radius:6px;background:#fff;color:#142134;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:12px 20px}.card{min-width:0;background:#fff;border:1px solid #c8d0da;border-radius:8px;overflow:hidden}.dark .card{background:#263140;border-color:#4a586b}.label{text-align:center;padding:9px;font-weight:650}.stage{height:640px;position:relative;overflow:hidden}.stage:after{content:'';position:absolute;left:10%;right:10%;bottom:28px;border-bottom:1px solid #b6bdc8}.stage img{position:absolute;max-width:none;cursor:zoom-in}.smallgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;padding:16px 30px}.smallstage{height:120px;position:relative;border-bottom:1px solid #99a4b2}.smallstage img{position:absolute;max-width:none;image-rendering:auto}.details{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:10px 24px}.detailrow{display:contents}.crop{height:270px;position:relative;overflow:hidden;border:1px solid #a6b1bd;background:#fff}.dark .crop{background:#263140}.crop img{position:absolute;max-width:none}.cap{position:absolute;bottom:0;left:0;right:0;background:#e8edf4e8;color:#17212f;text-align:center;font-size:14px;padding:5px}.capture header{height:110px}.capture nav{display:none}dialog{width:95vw;height:95vh;background:#b9c2ce}dialog img{max-width:100%;max-height:85vh;object-fit:contain}dialog::backdrop{background:#000b}section[hidden]{display:none!important}.note{padding:10px 24px;font-size:14px}body[data-mode=detail] h1{font-size:21px}
</style><header><h1>발로르 · 차수2 세로 실루엣 정돈</h1><p>차수1은 사용자 불합격입니다. 같은 본체높이·발선으로 폭 변화와 얼굴 비중을 비교합니다. 수정본은 사용자 판정 전입니다.</p><nav><button onclick="setMode('full')">전체 비교</button><button onclick="setMode('silhouette')">부위별 폭</button><button onclick="setMode('identity')">승인원화·1번·수정본</button><button onclick="setMode('detail')">디테일 대조</button><button onclick="setMode('small')">57 / 72px</button><button onclick="document.body.classList.toggle('dark')">밝은 / 어두운 배경</button></nav></header><section id="full"><div class="grid" id="grid"></div><p class="note">모발끝~발바닥을 같은 높이·발선으로 등비 표시합니다. 검끝·망토끝은 몸키에서 제외합니다. 이미지 클릭: 생성 원본.</p></section><section id="silhouette" hidden><div class="grid" id="silgrid"></div><div class="note" id="metrics"></div></section><section id="identity" hidden><div class="grid" id="identitygrid"></div></section><section id="detail" hidden><div class="details" id="details"></div><p class="note">원본과 SD의 같은 부위만 표시용 확대. 장비 실루엣·색·문장 보존을 대조하며 세부 선 수는 SD로 단순화합니다.</p></section><section id="small" hidden><p class="note">본체 57CSSpx · 갤러리 미리보기</p><div id="s57" class="smallgrid"></div><p class="note">본체 72CSSpx · 실게임/실기기 검증 아님</p><div id="s72" class="smallgrid"></div></section><dialog id="zoom"><button onclick="this.parentElement.close()">닫기</button><p id="zoomlabel"></p><img id="zoomimage"></dialog><script>const DATA=__DATA__;
function zoom(a){document.getElementById('zoomlabel').textContent=a.label+' · '+a.width+'×'+a.height+' 원본';document.getElementById('zoomimage').src=a.file;document.getElementById('zoom').showModal()}
function register(){const full=[...document.querySelectorAll('.stage')].filter(e=>e.clientWidth>0),common=Math.min(560,...full.map(e=>{const a=DATA[+e.dataset.i];return (e.clientWidth-20)*a.bodyHeight/(a.boundsAlpha32[2]-a.boundsAlpha32[0])}));document.querySelectorAll('.stage,.smallstage').forEach(e=>{const a=DATA[+e.dataset.i],im=e.querySelector('img'),small=e.classList.contains('smallstage'),base=e.clientHeight-(small?1:28),target=small?+e.dataset.size:common,s=target/a.bodyHeight;im.style.width=a.width*s+'px';im.style.left=e.clientWidth/2-a.footX*s+'px';im.style.top=base-a.footY*s+'px';e.dataset.displayBodyHeight=a.bodyHeight*s;e.dataset.footBaseline=base})}
DATA.slice(0,3).forEach((a,i)=>{let d=document.createElement('div');d.className='card';d.innerHTML='<div class="label">'+a.label+'</div><div class="stage" data-i="'+i+'"><img src="'+a.file+'"></div>';d.querySelector('img').onclick=()=>zoom(a);document.getElementById('grid').append(d);[57,72].forEach(size=>{let s=document.createElement('div');s.innerHTML='<div class="label">'+a.label+'</div><div class="smallstage" data-i="'+i+'" data-size="'+size+'"><img src="'+a.file+'"></div>';document.getElementById('s'+size).append(s)})});
const names={face:'얼굴 / 두상',grip:'파란 감긴 그립 · 은색 폼멜',guard:'날개 가드 · 붉은 마름모',lion:'전신 측면 사자',shield:'카이트실드 · 검은 날개 / 십자',cape:'청색 망토 · 흰 안감 / 용',pins:'원형 핀 · 연결끈 없음'};
Object.entries(names).forEach(([key,label])=>{[DATA[3],DATA[2]].forEach(a=>{const b=a.detailROIs[key],w=b[2]-b[0],h=b[3]-b[1];let d=document.createElement('div');d.className='crop';d.dataset.w=w;d.dataset.h=h;d.dataset.x=b[0];d.dataset.y=b[1];d.dataset.nativew=a.width;d.innerHTML='<img src="'+a.file+'"><div class="cap">'+a.label+' · '+label+'</div>';document.getElementById('details').append(d)})});
function crops(){document.querySelectorAll('.crop').forEach(e=>{let s=Math.min((e.clientWidth-12)/e.dataset.w,(e.clientHeight-34)/e.dataset.h);let im=e.querySelector('img');im.style.width=e.dataset.nativew*s+'px';im.style.left=(e.clientWidth-e.dataset.w*s)/2-e.dataset.x*s+'px';im.style.top=(e.clientHeight-28-e.dataset.h*s)/2-e.dataset.y*s+'px';im.style.clipPath='inset('+e.dataset.y*s+'px '+(im.naturalWidth-Number(e.dataset.x)-Number(e.dataset.w))*s+'px '+(im.naturalHeight-Number(e.dataset.y)-Number(e.dataset.h))*s+'px '+e.dataset.x*s+'px)'})}
[0,1,2].forEach(i=>{const a=DATA[i],d=document.createElement('div');d.className='card';d.innerHTML='<div class="label">'+a.label+'</div><div class="stage marked" data-i="'+i+'"><img src="'+a.file+'"><svg style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none"></svg></div>';document.getElementById('silgrid').append(d)});
[3,1,2].forEach(i=>{const a=DATA[i],d=document.createElement('div');d.className='card';d.innerHTML='<div class="label">'+a.label+'</div><div class="stage" data-i="'+i+'"><img src="'+a.file+'"></div>';d.querySelector('img').onclick=()=>zoom(a);document.getElementById('identitygrid').append(d)});
const LABELS={shoulders:'견갑 포함 어깨',chest:'흉곽 추정',waist:'허리 추정',arms:'오른상완→중심 거리',shield:'방패 자체 가로폭',cape:'망토 좌우폭',feet:'양발 외곽폭'};
const colors=['#df351f','#b81c81','#a86500','#148f65','#1476cf','#7255bd','#2c6274'];
function mark(){document.querySelectorAll('.marked').forEach(e=>{const a=DATA[+e.dataset.i],im=e.querySelector('img'),s=parseFloat(im.style.width)/a.width,l=parseFloat(im.style.left),t=parseFloat(im.style.top);e.querySelector('svg').innerHTML=Object.entries(a.widthMeasurements).map(([key,m],i)=>{if(m.applicable===false)return '';const x1=l+m.x1*s,x2=l+m.x2*s,y=t+m.y*s,c=colors[i];return '<line x1="'+x1+'" x2="'+x2+'" y1="'+y+'" y2="'+y+'" stroke="'+c+'" stroke-width="2"/><text x="'+x1+'" y="'+(y-5)+'" fill="'+c+'" font-size="12" font-weight="700">'+LABELS[key]+'</text>'}).join('')})}
document.getElementById('metrics').innerHTML='<p>가이드선은 비교페이지 표시용이며 PNG에 그리지 않았습니다. 아래 수치는 native 수동 ROI의 폭÷모발끝~발바닥 높이, 가려진 몸통/팔은 추정입니다. 사용자 확정규격이나 미적합격 점수가 아닙니다.</p><table style="width:100%;border-collapse:collapse">'+Object.entries(LABELS).map(([key,label])=>'<tr><th style="text-align:left">'+label+'</th>'+DATA.slice(0,3).map(a=>{const m=a.widthMeasurements[key];if(m.applicable===false)return '<td>해당없음</td>';return '<td>'+((m.x2-m.x1)/a.bodyHeight*100).toFixed(1)+'% ±'+(m.errorPx/a.bodyHeight*100).toFixed(1)+'%p</td>'}).join('')+'</tr>').join('')+'<tr><th style="text-align:left">머리포함 머리높이/본체</th>'+DATA.slice(0,3).map(a=>'<td>'+((a.chin-a.hairTop)/a.bodyHeight*100).toFixed(1)+'%</td>').join('')+'</tr><tr><th style="text-align:left">전체 장비포함 외곽/본체</th>'+DATA.slice(0,3).map(a=>'<td>'+((a.boundsAlpha32[2]-a.boundsAlpha32[0])/a.bodyHeight*100).toFixed(1)+'%</td>').join('')+'</tr></table>';
function setMode(m){document.body.dataset.mode=m;['full','detail','small','silhouette','identity'].forEach(k=>document.getElementById(k).hidden=k!==m);register();crops();mark()}window.addEventListener('resize',()=>{register();crops();mark()});document.body.classList.toggle('capture',location.search.includes('capture'));setMode('full');</script></html>'''.replace('__DATA__',json.dumps(data,ensure_ascii=False))
(R/'index.html').write_text(html,encoding='utf-8')
print(json.dumps([dict(file=x['file'],size=[x['width'],x['height']],bounds=x['boundsAlpha32'],alpha=x['alpha']) for x in data],ensure_ascii=False))
